function draw(container: HTMLElement): void {
  container.innerHTML = `
    <div class="card">
      <h3>${title}</h3>
      <button type="button" data-act="run">실행</button>
    </div>`;
}

// 이 문자열이 브라우저에서 진짜 요소들로 바뀐다 → 그게 DOM (5장)

/* 색·간격은 공용 토큰을 쓴다 — 자체 색을 박지 않는다 */
.my-widget-card {
  background: var(--bg-secondary);
  color: var(--text-primary);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
}

/* 위젯 전용 클래스에만 스타일을 건다 (전역 요소 선택자 X) */
/* 컨테이너 자체에 레이아웃을 걸지 않는다 — 내부 wrapper 에 건다 */

(function (): void {
  Toolbox.register({
    id: 'burnnote',
    title: t('widgets.burnnote.title', undefined, '사라지는 쪽지'),
    category: 'tool',
    tabs: [{
      id: 'app',
      label: t('burnnote.tab', undefined, '쪽지'),
      build: function (container: HTMLElement): void {
        draw(container);          // ← 여기서 DOM 을 만든다
      }
    }]
  });
})();
